def gen(rng):
    def title(n):
        s = ''
        while n:
            n, r = divmod(n - 1, 26)
            s = chr(65 + r) + s
        return s
    def fmt(toks):
        return str(len(toks)) + '\n' + '\n'.join(map(str, toks))
    tests = [fmt(['A']), fmt(['1']), fmt(['Z', '26', 'AA', '27']),
             fmt(['AZ', '52', 'BA', '53', 'ZZ', '702', 'AAA', '703']),
             fmt(['ZZZ', '18278', 'AAAA', '18279'])]
    for _ in range(14):
        toks = []
        for _ in range(rng.randint(1, 8)):
            v = rng.randint(1, 3000)
            toks.append(rng.choice([str(v), title(v)]))
        tests.append(fmt(toks))
    top = 10 ** 9
    special = []
    p = 26
    while p <= top:
        for d in (-1, 0, 1):
            if 1 <= p + d <= top:
                special.append(p + d)
        p *= 26
    special.append(top)
    def big(mode):
        toks = []
        for i in range(10000):
            if mode == 0:
                v = rng.randint(1, top)
            elif mode == 1:
                v = rng.choice(special)
            elif mode == 2:
                v = top - rng.randint(0, 5000)
            else:
                v = rng.randint(1, 10 ** rng.randint(1, 9))
            toks.append(rng.choice([str(v), title(v)]))
        return fmt(toks)
    for mode in range(4):
        tests.append(big(mode))
    tests.append(fmt([title(top)] * 10000))
    return tests
